    constructor(C _c) { c = _c; }

    function run(uint256 burnAmount) public {
        require(burnAmount > 0);
        uint256 supplyBefore = c.totalSupply();
        uint256 ownerBalanceBefore = c.balanceOf(msg.sender);
        require(burnAmount <= ownerBalanceBefore);
        uint256 balBefore = c.balanceOf(msg.sender);
        uint256 supplyBefore2 = c.totalSupply();
        c.burn(burnAmount);
        uint256 supplyAfter = c.totalSupply();
