contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, uint256 mintedAmount) public payable {
        require(true);

        uint256 supplyBefore = c.totalSupply();
        uint256 oldTargetBalance = c.balanceOf(target);

        bool reverted;
        try c.mintToken(target, mintedAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(c.balanceOf(target) >= oldTargetBalance && c.balanceOf(target) - oldTargetBalance == mintedAmount);
            assert(c.totalSupply() >= supplyBefore && c.totalSupply() - supplyBefore == mintedAmount);
        } else {
            assert(c.balanceOf(target) == oldTargetBalance);
            assert(c.totalSupply() == supplyBefore);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, uint256 mintedAmount) public payable {
        require(true);

        uint256 supplyBefore = c.totalSupply();
        uint256 targetBefore = c.balanceOf(target);

        bool success = c.mintToken(target, mintedAmount);

        assert(
            success
                ? (c.balanceOf(target) >= targetBefore && c.balanceOf(target) - targetBefore == mintedAmount
                   && c.totalSupply() >= supplyBefore && c.totalSupply() - supplyBefore == mintedAmount)
                : (c.balanceOf(target) == targetBefore && c.totalSupply() == supplyBefore)
        );
    }
}
